export const gracefullyCloseSet = new Set<() => Promise<void>>();
const killSet = new Set<() => void>();

export async function gracefullyCloseAll() {
  await Promise.all(Array.from(gracefullyCloseSet).map(gracefullyClose => gracefullyClose().catch(e => {})));
}

export function gracefullyProcessExitDoNotHang(code: number, onExit?: () => Promise<void>) {
  // Force exit after 30 seconds.
  const beforeExit = onExit ? () => onExit().catch(() => {}) : () => Promise.resolve();
  // eslint-disable-next-line no-restricted-syntax
  const callback = () => beforeExit().then(() => processExit(code));

  setTimeout(callback, 30000);
  // Meanwhile, try to gracefully close all browsers.
  gracefullyCloseAll().then(callback);
}

function exitHandler() {
  for (const kill of killSet)
    kill();
